using Karamchari.Core.Domain.Primitives;
using Karamchari.Core.Multitenancy;

namespace Karamchari.Intelligence.Domain.Workforce;

/// <summary>
/// A recommendation generated by the engine for a specific employee or manager.
/// Lifecycle: Open → Resolved (or Dismissed).
/// </summary>
public sealed class WorkforceRecommendation : AggregateRoot<Guid>, ITenantOwned
{
    /// <inheritdoc/>
    public string TenantId { get; private set; } = string.Empty;

    /// <summary>Employee this recommendation targets.</summary>
    public Guid EmployeeId { get; private set; }

    /// <summary>Action type the recommendation suggests.</summary>
    public WorkforceRecommendationType Type { get; private set; }

    /// <summary>Urgency of this recommendation.</summary>
    public RecommendationPriority Priority { get; private set; }

    /// <summary>Human-readable explanation of why this recommendation was raised.</summary>
    public string Rationale { get; private set; } = string.Empty;

    /// <summary>Score that triggered this recommendation (e.g. BurnoutScore=86).</summary>
    public decimal TriggerScore { get; private set; }

    /// <summary>UTC timestamp when the recommendation was generated.</summary>
    public DateTime CreatedAt { get; private set; }

    /// <summary>UTC timestamp when the recommendation was resolved. Null if still open.</summary>
    public DateTime? ResolvedAt { get; private set; }

    /// <summary>Who resolved it, if resolved.</summary>
    public string? ResolvedBy { get; private set; }

    private WorkforceRecommendation() { }

    /// <summary>Creates a new open recommendation.</summary>
    public static WorkforceRecommendation Raise(
        string tenantId,
        Guid employeeId,
        WorkforceRecommendationType type,
        RecommendationPriority priority,
        string rationale,
        decimal triggerScore)
    {
        if (string.IsNullOrWhiteSpace(rationale))
            throw new ArgumentException("Rationale is required for auditability.", nameof(rationale));

        return new WorkforceRecommendation
        {
            Id = Guid.NewGuid(),
            TenantId = tenantId,
            EmployeeId = employeeId,
            Type = type,
            Priority = priority,
            Rationale = rationale,
            TriggerScore = triggerScore,
            CreatedAt = DateTime.UtcNow
        };
    }

    /// <summary>Marks recommendation as resolved.</summary>
    public void Resolve(string resolvedBy)
    {
        if (ResolvedAt.HasValue) return; // idempotent
        ResolvedAt = DateTime.UtcNow;
        ResolvedBy = resolvedBy;
    }
}
